#include <torch/script.h>
#include <iostream>
int main(int argc, char** argv) {
  if (argc != 2) return 2;
  torch::NoGradGuard guard;
  auto model = torch::jit::load(argv[1], torch::kCPU);
  model.eval();
  auto result = model.forward({torch::zeros({1, 45})}).toTensor();
  if (result.sizes() != torch::IntArrayRef({1, 12}) || !torch::isfinite(result).all().item<bool>()) return 3;
  std::cout << "Deployment LibTorch load/forward OK: [1,45] -> [1,12]" << std::endl;
}
